contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run the test: caller provides an amount to send to c when calling play.
    // We observe pot before and after, address(c).balance before and after, and whether the call reverted.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // Observe before-values
        uint pot_before = c.pot();
        uint bal_before = address(c).balance;

        bool reverted;
        // Call play with given amount
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pot_after = c.pot();
        uint bal_after = address(c).balance;

        // General rule:
        // - If the call reverted, it must be because amount != TICKET_AMOUNT, so pot and balance unchanged.
        // - If the call did not revert, then amount == TICKET_AMOUNT, and exactly one of two cases holds:
        //    * Random != 0 (no payout): pot increased by amount and contract balance increased by amount.
        //    * Random == 0 (payout to player): pot becomes 0 and contract balance decreased by (pot_before + amount) - FEE_AMOUNT.
        // We cannot observe the random directly, so express as: if not reverted then either pot_after == pot_before + amount
        // and bal_after == bal_before + amount, or pot_after == 0 and bal_after + (pot_before + amount) == bal_before + FEE_AMOUNT.

        assert(
            // If reverted: pot and balance unchanged
            (reverted && pot_after == pot_before && bal_after == bal_before)
            ||
            // If not reverted: amount must equal ticket price and one of the two observable outcomes holds
            (!reverted && amount == C(address(c)).TICKET_AMOUNT() && (
                // loser: pot increased by amount and contract balance increased by amount
                (pot_after == pot_before + amount && bal_after == bal_before + amount)
                ||
                // winner: pot reset to 0, and the net change in contract balance equals -(pot_before + amount) + FEE_AMOUNT
                (pot_after == 0 && bal_after + (pot_before + amount) == bal_before + C(address(c)).FEE_AMOUNT())
            ))
        );
    }

    // Receive funds when contract is sent Ether externally (used to fund test for c.play calls)
    receive() external payable {}
}

